// ---------- Hilfen ----------
const pad = n => String(n).padStart(2, "0");
const isoOf = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
const hm = m => `${pad(Math.floor(m / 60))}:${pad(m % 60)}`;
const parseIso = s => { const [y, m, d] = s.split("-").map(Number); return new Date(y, m - 1, d); };
const WD = ["So", "Mo", "Di", "Mi", "Do", "Fr", "Sa"];
const fg = Color.dynamic(new Color("#000000"), new Color("#FFFFFF"));
const fg2 = Color.dynamic(new Color("#6E6E73"), new Color("#98989D"));
const bg = Color.dynamic(new Color("#FFFFFF"), new Color("#1C1C1E"));

function fm() { try { return FileManager.iCloud(); } catch (e) { return FileManager.local(); } }

function loadSynced() {
  const f = fm(), p = f.joinPath(f.documentsDirectory(), FILE);
  if (!f.fileExists(p)) return null;
  try { if (f.isFileStoredIniCloud && f.isFileStoredIniCloud(p)) f.downloadFileFromiCloud(p); } catch (e) {}
  try { return JSON.parse(f.readString(p)); } catch (e) { return null; }
}
function saveSynced(obj) {
  const f = fm(); f.writeString(f.joinPath(f.documentsDirectory(), FILE), JSON.stringify(obj));
}

function embedEvents() {
  return EMBED.map(([md, s, e, t, c]) => {
    const mm = +md.slice(0, 2), y = mm >= 8 ? 2026 : 2027;
    return [`${y}-${md.slice(0, 2)}-${md.slice(2)}`, s, e, t, c, 0];
  });
}

// ---------- Daten ----------
async function getData() {
  if (!config.runsInWidget) {
    const clip = Pasteboard.paste() || "";
    if (clip.startsWith("FORM12:")) {
      try {
        const obj = JSON.parse(clip.slice(7)); saveSynced(obj);
        const a = new Alert(); a.title = "Widget aktualisiert"; a.message = `${obj.ev.length} Termine übernommen.`; a.addAction("OK"); await a.present();
      } catch (e) {
        const a = new Alert(); a.title = "Konnte Daten nicht lesen"; a.message = String(e); a.addAction("OK"); await a.present();
      }
    }
  }
  const today = isoOf(new Date());
  const s = loadSynced();
  const useSync = s && s.ev && s.ev.some(x => x[0] >= today);
  let ev = useSync ? s.ev : embedEvents();
  // Für Tage, die der Abgleich nicht mehr abdeckt, den Standard-Plan ergänzen
  if (useSync) { const last = s.ev.reduce((m, x) => x[0] > m ? x[0] : m, ""); ev = ev.concat(embedEvents().filter(x => x[0] > last)); }
  return { ev, stats: useSync && s.stats && s.stats.d === today ? s.stats : null, synced: useSync ? s.gen : null };
}

// ---------- Zeichnen ----------
function ring(value, color, size, width, label) {
  const ctx = new DrawContext(); ctx.size = new Size(size, size); ctx.opaque = false; ctx.respectScreenScale = true;
  const r = (size - width) / 2, c = size / 2;
  const arc = (from, to, col) => {
    const pts = []; const steps = Math.max(2, Math.round(60 * (to - from)));
    for (let i = 0; i <= steps; i++) { const a = -Math.PI / 2 + 2 * Math.PI * (from + (to - from) * i / steps); pts.push(new Point(c + r * Math.cos(a), c + r * Math.sin(a))); }
    const p = new Path(); p.addLines(pts); ctx.addPath(p); ctx.setStrokeColor(col); ctx.setLineWidth(width); ctx.strokePath();
  };
  arc(0, 1, new Color("#8E8E93", 0.25));
  if (value > 0) arc(0, Math.min(1, value), new Color(color));
  ctx.setTextAlignedCenter(); ctx.setFont(Font.boldSystemFont(size / 4.4)); ctx.setTextColor(Color.dynamic(new Color("#000"), new Color("#fff")));
  ctx.drawTextInRect(label, new Rect(0, c - size / 7, size, size / 3.2));
  return ctx.getImage();
}

function progress() {
  const t = new Date(), s = parseIso(START), e = parseIso(END);
  const total = Math.round((e - s) / 864e5) + 1, day = Math.round((new Date(t.getFullYear(), t.getMonth(), t.getDate()) - s) / 864e5) + 1;
  const pw = 1 + Math.floor((parseIso(isoOf(t)) - s) / 864e5 / 7);
  return { total, day: Math.max(0, Math.min(total, day)), pw, before: day < 1 };
}

function eventsFor(ev, iso) { return ev.filter(x => x[0] === iso).sort((a, b) => a[1] - b[1]); }

function upcoming(ev, n) {
  const now = new Date(), iso = isoOf(now), min = now.getHours() * 60 + now.getMinutes();
  return ev.filter(x => x[0] > iso || (x[0] === iso && x[2] > min)).sort((a, b) => a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] - b[1]).slice(0, n);
}

function addEventRow(stack, x, opts = {}) {
  const row = stack.addStack(); row.centerAlignContent(); row.spacing = 6;
  const bar = row.addStack(); bar.size = new Size(4, opts.h || 26); bar.cornerRadius = 2; bar.backgroundColor = new Color((CAT[x[4]] || CAT.eigen)[0]);
  const col = row.addStack(); col.layoutVertically();
  const iso = isoOf(new Date());
  const d = parseIso(x[0]); const dayLabel = x[0] === iso ? "" : `${WD[d.getDay()]} `;
  const t1 = col.addText(`${dayLabel}${hm(x[1])}–${hm(x[2])}`); t1.font = Font.mediumSystemFont(opts.small ? 10 : 11); t1.textColor = fg2;
  const t2 = col.addText((x[5] ? "✓ " : "") + x[3]); t2.font = Font.semiboldSystemFont(opts.small ? 13 : 13); t2.textColor = fg; t2.lineLimit = opts.lines || 1;
  if (x[5]) t2.textOpacity = 0.5;
}

function header(w, p) {
  const h = w.addStack(); h.centerAlignContent();
  const t = h.addText("FORM 12"); t.font = Font.heavySystemFont(11); t.textColor = new Color("#FF3B30");
  h.addSpacer();
  const r = h.addText(p.before ? `Start ${START.slice(8)}.${START.slice(5, 7)}.` : p.pw <= 12 ? `Woche ${Math.max(1, p.pw)}/12` : "Lesereise"); r.font = Font.mediumSystemFont(11); r.textColor = fg2;
}

// ---------- Widgets ----------
function small(data) {
  const w = new ListWidget(); w.backgroundColor = bg; w.setPadding(12, 12, 12, 12);
  const p = progress(); header(w, p); w.addSpacer(6);
  const nx = upcoming(data.ev, 2);
  if (nx[0]) { addEventRow(w, nx[0], { lines: 2, h: 34 }); }
  w.addSpacer();
  if (nx[1]) { const t = w.addText(`danach ${hm(nx[1][1])} ${nx[1][3]}`); t.font = Font.systemFont(10); t.textColor = fg2; t.lineLimit = 1; }
  w.addSpacer(4);
  const img = new DrawContext(); img.size = new Size(130, 5); img.opaque = false; img.respectScreenScale = true;
  img.setFillColor(new Color("#8E8E93", 0.25)); img.fillRect(new Rect(0, 0, 130, 5));
  img.setFillColor(new Color("#FF3B30")); img.fillRect(new Rect(0, 0, 130 * p.day / p.total, 5));
  const im = w.addImage(img.getImage()); im.imageSize = new Size(130, 5);
  const ft = w.addText(p.before ? "bald geht's los" : `Tag ${p.day} von ${p.total}`); ft.font = Font.systemFont(10); ft.textColor = fg2;
  return w;
}

function rings(stack, data, size) {
  const st = data.stats; const p = progress();
  const today = eventsFor(data.ev, isoOf(new Date()));
  const done = st ? st.done : today.filter(x => x[5]).length, total = st ? st.total : today.length;
  const items = [
    ["Heute", total ? done / total : 0, "#FF3B30", `${done}/${total}`],
    ["Training", st && st.tr[1] ? st.tr[0] / st.tr[1] : 0, "#FF2D55", st ? `${st.tr[0]}/${st.tr[1]}` : "–"],
    ["Wasser", st && st.bt ? st.wa / st.bt : 0, "#5AC8FA", st ? `${st.wa}/${st.bt}` : "–"],
    ["Programm", p.day / p.total, "#AF52DE", `${Math.round(p.day / p.total * 100)}%`]
  ];
  const grid = stack.addStack(); grid.layoutVertically(); grid.spacing = 4;
  for (let r = 0; r < 2; r++) {
    const row = grid.addStack(); row.spacing = 8;
    for (let c = 0; c < 2; c++) {
      const [n, v, col, l] = items[r * 2 + c];
      const cell = row.addStack(); cell.layoutVertically(); cell.centerAlignContent();
      const im = cell.addImage(ring(v, col, size, size / 8, l)); im.imageSize = new Size(size, size);
      const t = cell.addText(n); t.font = Font.systemFont(9); t.textColor = fg2; t.centerAlignText();
    }
  }
}

function medium(data) {
  const w = new ListWidget(); w.backgroundColor = bg; w.setPadding(12, 14, 12, 14);
  const p = progress(); header(w, p); w.addSpacer(8);
  const body = w.addStack(); body.spacing = 14;
  rings(body, data, 40);
  const right = body.addStack(); right.layoutVertically(); right.spacing = 6;
  upcoming(data.ev, 3).forEach(x => addEventRow(right, x, { small: true }));
  w.addSpacer();
  return w;
}

function large(data) {
  const w = new ListWidget(); w.backgroundColor = bg; w.setPadding(14, 16, 14, 16);
  const p = progress(); header(w, p);
  const now = new Date(); const t = w.addText(`${WD[now.getDay()]}, ${now.getDate()}.${now.getMonth() + 1}.`); t.font = Font.boldSystemFont(20); t.textColor = fg;
  w.addSpacer(6);
  const top = w.addStack(); top.spacing = 12; rings(top, data, 44);
  const info = top.addStack(); info.layoutVertically(); info.spacing = 3;
  const st = data.stats;
  const lines = st ? [`🍽 ${st.ke} / ${st.kp} kcal`, `💧 ${st.wa} von ${st.bt} Flaschen`, `📖 ${st.read === 0 ? "Lesen im Plan" : st.read > 0 ? st.read + " Abschnitte voraus" : -st.read + " Abschnitte offen"}`, `🧠 Lernen ${st.learn[0]}/${st.learn[1]}`, `🌿 ${st.streak} Tage Reflexion in Folge`]
    : ["Tippe in der App auf", "„Widget aktualisieren“,", "um Häkchen, Wasser und", "Kalorien zu sehen."];
  lines.forEach(l => { const x = info.addText(l); x.font = Font.systemFont(11); x.textColor = fg2; });
  w.addSpacer(10);
  const iso = isoOf(now), min = now.getHours() * 60 + now.getMinutes();
  let list = eventsFor(data.ev, iso).filter(x => x[2] > min || x[5]);
  if (!list.length) list = upcoming(data.ev, 6);
  list.slice(0, 6).forEach(x => { addEventRow(w, x, { small: true, h: 24 }); w.addSpacer(4); });
  w.addSpacer();
  if (data.synced) { const f = w.addText("Stand: " + new Date(data.synced).toLocaleString("de-DE", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" })); f.font = Font.systemFont(9); f.textColor = fg2; }
  return w;
}


// ---------- iPad: extra groß ----------
function extraLarge(data) {
  const w = new ListWidget(); w.backgroundColor = bg; w.setPadding(16, 18, 16, 18);
  const p = progress(); header(w, p);
  const now = new Date(); const iso = isoOf(now), min = now.getHours() * 60 + now.getMinutes();
  const t = w.addText(`${WD[now.getDay()]}, ${now.getDate()}.${now.getMonth() + 1}.`); t.font = Font.boldSystemFont(22); t.textColor = fg;
  w.addSpacer(8);
  const body = w.addStack(); body.spacing = 18; body.topAlignContent();
  const left = body.addStack(); left.layoutVertically(); left.spacing = 5; left.size = new Size(300, 0);
  const top = left.addStack(); top.spacing = 10; rings(top, data, 46);
  left.addSpacer(6);
  let list = eventsFor(data.ev, iso).filter(x => x[2] > min || x[5]);
  if (!list.length) list = upcoming(data.ev, 9);
  list.slice(0, 9).forEach(x => addEventRow(left, x, { small: true, h: 24 }));
  const right = body.addStack(); right.layoutVertically(); right.spacing = 10;
  for (let i = 1; i <= 3; i++) {
    const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i), di = isoOf(d);
    const col = right.addStack(); col.layoutVertically(); col.spacing = 3;
    const h = col.addText(`${WD[d.getDay()]}, ${d.getDate()}.${d.getMonth() + 1}.`); h.font = Font.boldSystemFont(13); h.textColor = fg;
    const evs = eventsFor(data.ev, di);
    if (!evs.length) { const n = col.addText("frei"); n.font = Font.systemFont(11); n.textColor = fg2; }
    evs.slice(0, 5).forEach(x => {
      const r = col.addStack(); r.spacing = 5; r.centerAlignContent();
      const dot = r.addStack(); dot.size = new Size(6, 6); dot.cornerRadius = 3; dot.backgroundColor = new Color((CAT[x[4]] || CAT.eigen)[0]);
      const tx = r.addText(`${hm(x[1])} ${x[3]}`); tx.font = Font.systemFont(11); tx.textColor = fg2; tx.lineLimit = 1;
    });
    if (evs.length > 5) { const m = col.addText(`+ ${evs.length - 5} weitere`); m.font = Font.systemFont(10); m.textColor = fg2; }
  }
  w.addSpacer();
  if (data.synced) { const f = w.addText("Stand: " + new Date(data.synced).toLocaleString("de-DE", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" })); f.font = Font.systemFont(9); f.textColor = fg2; }
  return w;
}

// ---------- Sperrbildschirm ----------
function shortTitle(x) { return x[3].replace(/^Schach W\d+: /, "Schach: ").replace(/\s*\(.*\)$/, ""); }
function accRect(data) {
  const w = new ListWidget(); w.setPadding(0, 0, 0, 0);
  const nx = upcoming(data.ev, 2), iso = isoOf(new Date());
  const h = w.addText("FORM 12"); h.font = Font.heavySystemFont(10); h.textOpacity = 0.7;
  if (!nx[0]) { const t = w.addText("Plan abgeschlossen 🎉"); t.font = Font.semiboldSystemFont(13); return w; }
  const day = nx[0][0] === iso ? "" : `${WD[parseIso(nx[0][0]).getDay()]} `;
  const a = w.addText(`${day}${hm(nx[0][1])}–${hm(nx[0][2])}`); a.font = Font.mediumSystemFont(11);
  const b = w.addText(shortTitle(nx[0])); b.font = Font.semiboldSystemFont(14); b.lineLimit = 1;
  if (nx[1]) { const c = w.addText(`danach ${hm(nx[1][1])} ${shortTitle(nx[1])}`); c.font = Font.systemFont(11); c.textOpacity = 0.75; c.lineLimit = 1; }
  return w;
}
function accCircle(data) {
  const w = new ListWidget(); w.addAccessoryWidgetBackground = true; w.setPadding(2, 2, 2, 2);
  const today = eventsFor(data.ev, isoOf(new Date()));
  const st = data.stats, done = st ? st.done : today.filter(x => x[5]).length, total = st ? st.total : today.length;
  const ctx = new DrawContext(); ctx.size = new Size(60, 60); ctx.opaque = false; ctx.respectScreenScale = true;
  const r = 25, c = 30;
  const arc = (to, alpha) => { const pts = []; for (let i = 0; i <= 60 * to; i++) { const a = -Math.PI / 2 + 2 * Math.PI * i / 60; pts.push(new Point(c + r * Math.cos(a), c + r * Math.sin(a))); } if (pts.length < 2) return; const p = new Path(); p.addLines(pts); ctx.addPath(p); ctx.setStrokeColor(new Color("#FFFFFF", alpha)); ctx.setLineWidth(6); ctx.strokePath(); };
  arc(1, 0.3); if (total && done) arc(Math.min(1, done / total), 1);
  ctx.setTextAlignedCenter(); ctx.setTextColor(Color.white());
  ctx.setFont(Font.boldSystemFont(15)); ctx.drawTextInRect(`${done}/${total}`, new Rect(0, 16, 60, 20));
  ctx.setFont(Font.systemFont(9)); ctx.drawTextInRect("heute", new Rect(0, 34, 60, 12));
  const im = w.addImage(ctx.getImage()); im.imageSize = new Size(60, 60); im.centerAlignImage();
  return w;
}
function accInline(data) {
  const w = new ListWidget(); const nx = upcoming(data.ev, 1)[0];
  const t = w.addText(nx ? `${hm(nx[1])} ${shortTitle(nx)}` : "Form 12 ✓"); return w;
}

// ---------- Start ----------
const data = await getData();
const fam = config.widgetFamily || "large";
const MAP = { small, medium, large, extraLarge, accessoryRectangular: accRect, accessoryCircular: accCircle, accessoryInline: accInline };
const widget = (MAP[fam] || large)(data);
if (APP_URL) widget.url = APP_URL;
widget.refreshAfterDate = new Date(Date.now() + 15 * 60 * 1000);
if (config.runsInWidget) { Script.setWidget(widget); }
else { await widget.presentLarge(); }
Script.complete();
